# Host-level customizations on fastpi (Docker/CUSTOMIZATIONS.md "Host"): security monitoring, auto-update, firewall persistence. No compose project, so only "all" runs it.
SMD=$(cd "$(dirname "${BASH_SOURCE[0]}")/../../../Server/4-Security-Monitoring" && pwd)
check host.security-timers '^active( active){7}$' "$(systemctl is-active security-scan.timer security-image-scan.timer security-av.timer security-av-hits.timer security-audit.timer security-access.timer security-code-scan.timer security-dt.timer | xargs)"
check host.security-units-installed '^0$' "$(n=0; for f in "$SMD"/security-*.service "$SMD"/security-*.timer; do cmp -s "$f" "/etc/systemd/system/$(basename "$f")" || n=$((n+1)); done; echo $n)"
# tower sleeps most days and its scans go stale with it; SecurityScanStale itself still reports those subjects.
check host.security-scan-fresh '^none$' "$(curl -s -m 5 http://127.0.0.1:9093/api/v2/alerts | python3 -c 'import json,sys; a=sorted({x["labels"]["alertname"] for x in json.load(sys.stdin) if x["labels"]["alertname"] in ("SecurityScanStale","ClamavScanStale","ContainerExporterStale") and not x["labels"].get("subject","").endswith("-tower")}); print(" ".join(a) or "none")')"
check host.auto-update-timer '^active active$' "$(systemctl is-active auto-update.timer image-cleanup.timer | xargs)"
check host.host-guard-persisted '^1$' "$(grep -c '^-A INPUT -i br-+ -j HOST-GUARD$' /etc/iptables/rules.v4 2>/dev/null || sudo -n grep -c '^-A INPUT -i br-+ -j HOST-GUARD$' /etc/iptables/rules.v4)"
check host.lan-guard '^1 1$' "$(sudo -n iptables -C INPUT -i eth0 -j HOST-LAN-GUARD 2>/dev/null && echo 1 || echo 0) $(sudo -n grep -c '^-A INPUT -i eth0 -j HOST-LAN-GUARD$' /etc/iptables/rules.v4)"
check host.sshd-forwarding '^allowtcpforwarding local permitopen 127\.0\.0\.1:\* localhost:\* \[::1\]:\* permitlisten none$' "$(sudo -n sshd -T | grep -E '^(allowtcpforwarding|permitopen|permitlisten) ' | xargs)"
check host.backup-rest '^active append-only beefy-only$' "$(systemctl is-active beefy-backup-rest.service) $(systemctl show -p ExecStart --value beefy-backup-rest.service | grep -q -- '--append-only' && echo append-only || echo NOT-append-only) $([ "$(systemctl show -p IPAddressAllow --value beefy-backup-rest.service)" = 192.168.1.102/32 ] && echo beefy-only || echo open)"
check host.backup-timers '^active active active$' "$(systemctl is-active fastpi-backup.timer fastpi-restore-test.timer beefy-repo-maint.timer | xargs)"
check host.textfile-perms '^pi:65046 2775$' "$(stat -c '%U:%g %a' /var/lib/node-exporter/textfile)"
check host.root-scripts '^0$' "$("$(dirname "${BASH_SOURCE[0]}")/../install-root-scripts.sh" --check)"
check host.beefy-repo-maint '^beefy-backup 0$' "$(systemctl show -p User --value beefy-repo-maint.service) $(sudo -n find /var/lib/beefy-backup ! -user beefy-backup | wc -l)"
check host.backup-scripts '^0$' "$(for p in backup.sh:fastpi-backup restore-test.sh:fastpi-restore-test beefy-repo-maint.sh:beefy-repo-maint; do sudo -n cmp -s "$SMD/../5-Backup/${p%%:*}" "/usr/local/sbin/${p##*:}" || echo x; done | wc -l)"
check host.backup-rest-nocreds '^-/run/credentials$' "$(systemctl show -p InaccessiblePaths --value beefy-backup-rest.service | grep -o -- '-/run/credentials')"
check host.claude-scratch '^enabled 0 [01]$' "$(systemctl is-enabled claude-scratch.service) $(n=0; cmp -s "$SMD/../8-Claude-Scratch/claude-scratch.service" /etc/systemd/system/claude-scratch.service || n=$((n+1)); cmp -s "$SMD/../8-Claude-Scratch/claude-remote-scratch.conf" /home/pi/.config/systemd/user/claude-remote.service.d/scratch.conf || n=$((n+1)); echo $n) $(mountpoint -q /tmp/claude-1000 && echo 1 || echo 0)"
check host.claude-restart-guard '^1 0$' "$([ "$(readlink -f /home/pi/.local/bin/claude-remote-safe-restart)" = "$(readlink -f "$SMD/../8-Claude-Scratch/claude-remote-safe-restart")" ] && echo 1 || echo 0) $(n=0; for u in claude-remote-restart.service claude-remote-restart.timer; do cmp -s "$SMD/../8-Claude-Scratch/$u" "/home/pi/.config/systemd/user/$u" || n=$((n+1)); done; echo $n)"
